/**
 * LAYER: Infrastructure
 * Contains: Build step that bundles the real @builderbot/bot core for the browser playground
 * Rules: Dev-only. Reads the open-source repo, writes one generated file. Never edit the output by hand.
 * GOAL: The playground runs exactly the engine the docs describe, not a re-implementation.
 *
 * Usage: node scripts/sync-playground.mjs [path-to-builderbot-repo]
 * Default source: ../builderbot (or $BUILDERBOT_DIR) — https://github.com/codigoencasa/builderbot
 */
import { execSync } from 'node:child_process'
import { mkdirSync, readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const REPO = resolve(process.argv[2] ?? process.env.BUILDERBOT_DIR ?? join(ROOT, '..', 'builderbot'))
const BOT = join(REPO, 'packages/bot')
const SHIM = join(ROOT, 'scripts/playground-shims/node.js')
const OUT = join(ROOT, 'src/lib/playground/bot.generated.js')

/** Module → expression for its default export (named exports come from the shim as they are). */
const NODE_MODULES = {
  console: 's',
  events: 's.EventEmitter',
  fs: 's',
  crypto: 's',
  async_hooks: 's',
  'body-parser': 's',
  cors: 's.cors',
  polka: 's.polka',
  'follow-redirects': 's',
  'mime-types': 's.mimeTypes',
  os: 's',
  path: 's',
  http: 's.http',
  https: 's.https',
  '@ffmpeg-installer/ffmpeg': 's.ffmpegInstaller',
  'fluent-ffmpeg': 's.ffmpeg',
  sharp: '() => ({})',
  picocolors: 'new Proxy({}, { get: () => (text) => text })',
}

const nodeShims = {
  name: 'playground-node-shims',
  setup(b) {
    b.onResolve({ filter: /.*/ }, ({ path }) => {
      const name = path.replace(/^node:/, '')
      return name in NODE_MODULES ? { path: name, namespace: 'shim' } : undefined
    })
    b.onLoad({ filter: /.*/, namespace: 'shim' }, ({ path }) => ({
      contents: `import * as s from ${JSON.stringify(SHIM)};\nexport * from ${JSON.stringify(SHIM)};\nexport default ${NODE_MODULES[path]};`,
      loader: 'js',
      resolveDir: ROOT,
    }))
  },
}

const version = JSON.parse(readFileSync(join(BOT, 'package.json'), 'utf8')).version
let commit = 'unknown'
try {
  commit = execSync('git rev-parse --short HEAD', { cwd: REPO }).toString().trim()
} catch {}

mkdirSync(dirname(OUT), { recursive: true })
await build({
  entryPoints: [join(BOT, 'src/index.ts')],
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2020',
  outfile: OUT,
  plugins: [nodeShims],
  define: {
    'process.env.NODE_ENV': '"test"',
    'process.env.DEBUG': 'undefined',
  },
  inject: [join(ROOT, 'scripts/playground-shims/globals.js')],
  legalComments: 'none',
  footer: { js: `export const BOT_VERSION = ${JSON.stringify(version)};` },
  banner: {
    js: `/* eslint-disable */\n// GENERATED by scripts/sync-playground.mjs from @builderbot/bot@${version} (builderbot@${commit}). MIT License. Do not edit.\n`,
  },
})
console.log(`playground synced: @builderbot/bot@${version} (builderbot@${commit})`)
